const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
export const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>JSON.parse(JSON.stringify(x));
let saved={};try{saved=JSON.parse(localStorage.getItem('openplay-review-v1')||'{}');}catch{}
const engine=new AudioEngine();
const state={tracks:clone(demoTracks),crates:saved.crates||[{id:'warm',name:'Warm up',tracks:['demo-2','demo-4','demo-6']},{id:'night',name:'Night shift',tracks:['demo-0','demo-1']},{id:'peak',name:'Peak time',tracks:['demo-3','demo-5']},{id:'close',name:'Closing',tracks:['demo-7']}],settings:{...defaultSettings(),...saved.settings},selected:'demo-0',crate:'all',search:'',sort:'title',sortDir:1,grid:false,columns:['title','artist','bpm','key','plays','album','duration'],decks:Array.from({length:4},(_,i)=>newDeck(i)),deckCount:2,focus:0,panel:null,quantize:true,autoplay:false,prepare:[],history:[],layout:'Vertical',analysis:false,fx:Array.from({length:2},()=>['LPF','Delay','Reverb'].map(name=>({name,on:false,depth:50,beat:'1/2',params:{}}))),fxFavorites:[],fxPresets:[],bank:0,samples:Array.from({length:4},()=>Array.from({length:8},()=>({track:null,mode:'Trigger',gain:80,playing:false}))),scratchBank:0,scratch:Array.from({length:4},()=>Array.from({length:8},()=>({track:null,start:'Start',keylock:false,repeat:false}))),flip:{armed:false,events:[],on:false,loop:false,saved:[],name:'Untitled Flip'},device:{connected:true,mode:'INT',noise:20,signal:90,feedback:true},mappings:[],midiLog:[],providerState:{},video:{text:'OPEN PLAY',color:'#ffffff',animation:'None',transition:'Crossfade',cross:0,image:null,auto:false,random:false,linked:true},link:{joined:false,tempo:124,peers:0},sessionSaved:false};
if(saved.tags)for(const t of state.tracks)Object.assign(t,saved.tags[t.id]||{});
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const time=v=>{v=Math.max(0,Number(v)||0);return `${Math.floor(v/60).toString().padStart(2,'0')}:${Math.floor(v%60).toString().padStart(2,'0')}.${Math.floor(v%1*10)}`;};
let noticeTimer;
function notify(message){$('#notice').textContent=message;$('#notice').classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').classList.remove('visible'),3500);}
function persist(){try{localStorage.setItem('openplay-review-v1',JSON.stringify({settings:state.settings,crates:state.crates,tags:Object.fromEntries(state.tracks.filter(t=>t.demo).map(t=>[t.id,Object.fromEntries(['title','artist','album','bpm','key','rating','comment','color','cues','savedLoops','grid','gridMarkers','locked'].map(k=>[k,t[k]]))]))}));state.sessionSaved=true;}catch{notify('Browser storage unavailable. Export a library backup to preserve changes.');}}
function dialog(title,html,setup){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();setup?.($('#modal-body'));}
$('#modal-close').onclick=()=>$('#modal').close();
function trackById(id){return state.tracks.find(t=>t.id===id);}
function filtered(){let a=state.tracks.filter(t=>!t.provider);if(state.crate==='prepare')a=a.filter(t=>state.prepare.includes(t.id));else if(state.crate==='stems')a=a.filter(t=>t.stemState==='Ready (simulation)');else if(state.crate==='history')a=a.filter(t=>state.history.some(h=>h.id===t.id));else {const c=state.crates.find(c=>c.id===state.crate);if(c)a=c.smart?a.filter(t=>Number(t[c.field])>=(Number(c.value)||0)):a.filter(t=>c.tracks.includes(t.id));}const q=state.search.toLowerCase();a=a.filter(t=>[t.title,t.artist,t.album,t.key,t.comment].some(s=>String(s||'').toLowerCase().includes(q)));return a.sort((a,b)=>{const x=a[state.sort],y=b[state.sort];return (typeof x==='number'?x-y:String(x||'').localeCompare(String(y||'')))*state.sortDir;});}
function renderCrates(){const q=$('#crate-search').value.toLowerCase();$('#crates').innerHTML=[['all','✳','All music'],['itunes','♫','iTunes / local'],['stems','≋','Prepared stems'],['prepare','◷','Prepare']].map(([id,icon,name])=>`<button data-crate="${id}" class="${state.crate===id?'active':''}"><span class="crate-icon">${icon}</span>${name}</button>`).join('')+'<div class="crate-section">CRATES</div>'+state.crates.filter(c=>c.name.toLowerCase().includes(q)).map(c=>`<button data-crate="${esc(c.id)}" draggable="true" class="${state.crate===c.id?'active':''}"><span class="crate-icon">${c.smart?'◇':'▰'}</span>${esc(c.name)}${c.favorite?' ★':''}</button>`).join('')+(state.settings['Show Streaming Services']?'<div class="crate-section">STREAMING · SIMULATION</div>'+Object.keys(providers).map(p=>`<button data-provider="${p}"><span class="crate-icon">○</span>${p}</button>`).join(''):'');}
function renderTracks(){const a=filtered();$('#tracks').innerHTML=state.grid?`<div class="art-grid">${a.map(t=>`<button class="art-card ${state.selected===t.id?'active':''}" data-track="${t.id}" draggable="true"><div class="art-cover" style="--art:${t.color}">◉</div><strong>${esc(t.title)}</strong><small>${esc(t.artist)} · ${t.bpm||'—'} BPM</small></button>`).join('')}</div>`:`<table><thead><tr><th style="width:28px"><button title="File status">◉</button></th>${state.columns.map(c=>`<th><button data-sort="${c}">${({duration:'LENGTH',title:'SONG'})[c]||c.toUpperCase()} ${state.sort===c?(state.sortDir===1?'▴':'▾'):''}</button></th>`).join('')}</tr></thead><tbody>${a.map(t=>`<tr tabindex="0" draggable="true" data-track="${t.id}" class="${t.id===state.selected?'selected':''}" aria-selected="${t.id===state.selected}"><td class="${t.missing?'problem':''}" title="${t.missing?'Missing file':t.locked?'Beatgrid locked':'Local audio'}">${t.missing?'⚠':t.locked?'▣':'♫'}</td>${state.columns.map(c=>`<td class="${c==='key'?'key':''}">${esc(c==='duration'?time(t.duration):c==='rating'?'★'.repeat(t.rating):t[c]??'—')}</td>`).join('')}</tr>`).join('')}</tbody></table>`;if(!a.length)$('#tracks').innerHTML='<div class="empty">No tracks here.<br><br>Import local audio, add tracks to this crate, or clear the search.</div>';$('#library-summary').textContent=`${a.length} tracks · ${time(a.reduce((n,t)=>n+t.duration,0))} · ${state.crates.find(c=>c.id===state.crate)?.name||state.crate}`;}
function padMarkup(d){const t=d.track, labels=d.tab==='Stems'?['Vocal','Melody','Bass','Drums','Vocal echo','Music echo','Music brake','Drum echo']:d.tab==='Loops'?Array.from({length:8},(_,i)=>t?.savedLoops[i]?.name||`Loop ${i+1}`):d.tab==='Pitch'?['0','+1','+2','+3','−4','−3','−2','−1']:d.tab==='Slicer'?Array.from({length:8},(_,i)=>`Slice ${i+1}`):Array.from({length:8},(_,i)=>t?.cues[i]?.name||'+');return labels.map((label,i)=>`<button class="pad ${d.tab==='Cues'&&t?.cues[i]?'set':''} ${d.tab==='Stems'&&i<4&&d.stems[i]?'active':''}" data-deck="${d.index}" data-action="pad" data-pad="${i}" style="--pad:${colors[i]}" title="${d.tab==='Cues'?'Click set/trigger; Shift-click delete; right-click edit':'Simulation where marked'}">${esc(label)}<small>${d.tab==='Cues'&&t?.cues[i]?time(t.cues[i].position):d.tab==='Stems'||d.tab==='Slicer'||d.tab==='Pitch'?'SIMULATED':(i+1)}</small></button>`).join('');}
function renderDecks(){document.body.className=`${document.body.classList.contains('day')?'day ':''}layout-${state.layout}${state.deckCount===4?' four-decks':''}`;$('#decks').innerHTML=state.decks.slice(0,state.deckCount).map(d=>{const t=d.track;return `<article class="deck ${state.focus===d.index?'focused':''}" style="--accent:${colors[d.index]}" data-drop-deck="${d.index}" data-focus="${d.index}"><div class="deck-head"><span class="deck-number">${d.index+1}</span><div class="deck-title"><strong>${esc(t?.title||'Drag song here')}</strong><small>${esc(t?.artist||'Select a library track and Load')}${t?' · '+time(t.duration):''}</small></div><span class="deck-key">${esc(t?.key||'—')}</span><button data-action="load" data-deck="${d.index}">Load</button><button data-action="eject" data-deck="${d.index}" aria-label="Eject deck ${d.index+1}">⏏</button></div><div class="deck-body"><div><nav class="deck-tabs" aria-label="Deck ${d.index+1} performance modes">${['Cues','Loops','Stems','Pitch','Slicer'].map(tab=>`<button data-action="tab" data-deck="${d.index}" data-tab="${tab}" class="${d.tab===tab?'active':''}">${tab}</button>`).join('')}</nav><div class="pads">${padMarkup(d)}</div><div class="loop-line"><button data-action="loopHalf" data-deck="${d.index}">½</button><button data-action="loop" data-deck="${d.index}" class="${d.loop?'active':''}">Loop ${d.loopLength}</button><button data-action="loopDouble" data-deck="${d.index}">×2</button><button data-action="loopIn" data-deck="${d.index}">IN</button><button data-action="loopOut" data-deck="${d.index}">OUT</button><button data-action="loopSave" data-deck="${d.index}">Save</button></div><div class="loop-line"><button data-action="jumpBack" data-deck="${d.index}">← ${d.loopLength}</button><button data-action="roll" data-deck="${d.index}">Hold roll</button><button data-action="jumpForward" data-deck="${d.index}">${d.loopLength} →</button><button data-action="grid" data-deck="${d.index}">Edit grid</button></div></div><div class="deck-disc"><div class="transport"><button data-action="sync" data-deck="${d.index}" class="${d.sync?'active':''}">SYNC</button><button data-action="cue" data-deck="${d.index}" title="Temporary cue">▮◀</button><button data-action="play" data-deck="${d.index}" aria-label="Play or pause deck ${d.index+1}" class="${d.playing?'active':''}">${d.playing?'❚❚':'▶'}</button></div><div class="platter" id="platter-${d.index}"><strong>${t?(t.bpm*d.rate).toFixed(1):'—'}</strong><small>BPM · ${((d.rate-1)*100).toFixed(1)}%</small><time id="time-${d.index}">${time(engine.position(d))}</time><small id="remain-${d.index}">−${time((t?.duration||0)-engine.position(d))}</small></div></div><label class="tempo-control" title="Tempo; key lock is simulated">±${d.pitchRange}%<input type="range" min="${-d.pitchRange}" max="${d.pitchRange}" step=".1" value="${(d.rate-1)*100}" data-tempo="${d.index}" aria-label="Deck ${d.index+1} tempo"></label></div><div class="deck-foot"><select data-mode="${d.index}" aria-label="Deck ${d.index+1} mode">${['INT','REL','ABS','THRU','WIR'].map(m=>`<option ${d.mode===m?'selected':''}>${m}</option>`).join('')}</select>${[['keylock','Key lock'],['slip','Slip'],['reverse','Reverse'],['repeat','Repeat']].map(([key,label])=>`<button data-action="${key}" data-deck="${d.index}" class="${d[key]?'active':''}">${label}${['keylock','slip','reverse'].includes(key)?' ◇':''}</button>`).join('')}<button data-action="range" data-deck="${d.index}">±${d.pitchRange}</button><button data-action="double" data-deck="${d.index}">Double</button><span class="spacer"></span><small class="muted">${d.mode==='INT'?'LOCAL AUDIO':'DEVICE SIMULATION'}</small></div><div class="wave-wrap" data-seek="${d.index}" tabindex="0" role="slider" aria-label="Deck ${d.index+1} play position" aria-valuemin="0" aria-valuemax="${t?.duration||48}" aria-valuenow="${engine.position(d)}"><canvas id="wave-${d.index}" width="900" height="100"></canvas><span class="playhead" id="head-${d.index}"></span><span class="wave-label">${t?.analyzed?'Decoded waveform':'Generated overview fixture'} · ${t?.bpm||'—'} BPM</span></div></article>`;}).join('');if(state.layout==='Vertical')$('#decks').insertAdjacentHTML('beforeend',`<section class="detail-waves" aria-label="Scrolling waveforms"><canvas id="detail-wave" width="320" height="330"></canvas><span>LOCAL WAVEFORMS · ±2s</span></section>`);drawWaves();renderMixer();}
function drawWaves(){for(const d of state.decks.slice(0,state.deckCount)){const c=$(`#wave-${d.index}`);if(!c)continue;const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);if(!d.track)continue;const buf=engine.buffers.get(d.track.id),a=buf?.getChannelData(0);for(let x=0;x<w;x+=3){let amp;if(a){const start=Math.floor(x/w*a.length),step=Math.max(1,Math.floor(a.length/w));amp=0;for(let k=0;k<step;k+=Math.max(1,Math.floor(step/20)))amp=Math.max(amp,Math.abs(a[start+k]||0));amp=Math.min(.95,amp*2.5);}else amp=.1+.6*Math.abs(Math.sin(x*.19+d.index)*Math.sin(x*.034));ctx.fillStyle=x%15<6?colors[d.index]:'#408498';ctx.fillRect(x,h/2-amp*h/2,2,amp*h);}const beat=60/(d.track.bpm||120);for(let p=d.track.grid||0;p<d.track.duration;p+=beat){const x=p/d.track.duration*w;ctx.fillStyle='#ffffff45';ctx.fillRect(x,0,1,h);}for(let i=0;i<d.track.cues.length;i++){const q=d.track.cues[i];if(q){ctx.fillStyle=colors[i%8];ctx.fillRect(q.position/d.track.duration*w,0,3,h);}}if(d.loop){ctx.fillStyle='#ffffff22';ctx.fillRect(d.loopIn/d.track.duration*w,0,(d.loopOut-d.loopIn)/d.track.duration*w,h);}}}
function drawDetailWave(){
 const canvas=$('#detail-wave');if(!canvas)return;const c=canvas.getContext('2d'),w=canvas.width,h=canvas.height,n=state.deckCount,col=w/n;c.clearRect(0,0,w,h);
 for(const d of state.decks.slice(0,n)){const x0=d.index*col,mid=x0+col/2,p=engine.position(d),t=d.track,buf=t&&engine.buffers.get(t.id),data=buf?.getChannelData(0);c.fillStyle='#070a0c';c.fillRect(x0,0,col-1,h);if(!t)continue;
  const bpm=t.bpm||120,beat=60/bpm,offset=t.grid||0;
  for(let y=0;y<h;y+=2){const sec=p+(y/h-.5)*4;let amp=0;if(data&&sec>=0&&sec<t.duration){const start=Math.floor(sec*buf.sampleRate);for(let j=0;j<100;j+=5)amp=Math.max(amp,Math.abs(data[start+j]||0));}amp=Math.min(1,amp*2);c.fillStyle=y%12<4?colors[d.index]:'#3486a8';c.fillRect(mid-amp*(col-28)/2,y,amp*(col-28),1.6);}
  const first=Math.ceil((p-2-offset)/beat);for(let b=first;b<first+4/beat+1;b++){const y=((b*beat+offset-p)/4+.5)*h;c.fillStyle=b%4===0?'#ffffff70':'#ffffff20';c.fillRect(x0,y,col,1);if(b%4===0){c.fillStyle='#aeb5ba';c.font='9px Arial';c.fillText(String(Math.floor(b/4)+1),x0+3,y-3);}}
  for(const [i,q]of t.cues.entries()){if(!q)continue;const y=((q.position-p)/4+.5)*h;if(y>=0&&y<h){c.fillStyle=colors[i%8];c.fillRect(x0,y,col,2);c.fillText(String(i+1),x0+col-12,y-3);}}
 }c.fillStyle='#fff';c.fillRect(0,h/2,w,1);
}
function renderMixer(){$('#mixer').innerHTML=state.decks.slice(0,state.deckCount).map(d=>`<div class="channel-strip" style="--accent:${colors[d.index]}"><strong>${d.index+1}</strong>${['trim','high','mid','low','filter'].map(k=>`<label class="knob-group">${k==='trim'?'GAIN':k.toUpperCase()}<input aria-label="Deck ${d.index+1} ${k}" type="range" data-mix="${d.index}:${k}" min="${k==='trim'?0:k==='filter'?-1:-24}" max="${k==='trim'?2:k==='filter'?1:6}" step="${['trim','filter'].includes(k)?'.01':'.5'}" value="${d[k]??(k==='trim'?1:0)}"></label>`).join('')}<label class="fader-group">LEVEL<input type="range" min="0" max="1" step=".01" value="${d.level??.8}" data-mix="${d.index}:level" aria-label="Deck ${d.index+1} level"></label><button data-action="pfl" data-deck="${d.index}" class="${d.pfl?'active':''}" title="Headphone cue simulation">CUE ◇</button></div>`).join('')+`<label class="crossfader">A — CROSSFADER — B<input id="crossfader" type="range" min="-1" max="1" step=".01" value="${engine.cross}" aria-label="Crossfader"></label>`;}
async function load(index,id=state.selected,options={}){const d=state.decks[index],t=trackById(id);if(!t)return notify('Select a track first.');if(d.playing&&state.settings['Lock Playing Deck'])return notify('Playing deck locked. Pause it before replacement.');const old=d.track?{id:d.track.id,position:engine.position(d)}:null;engine.pause(d);d.previous=old;d.track=t;d.position=options.position??(state.settings['Play from First Cue Point']?t.cues.find(Boolean)?.position||0:0);d.loop=false;d.tab='Cues';d.pitchRangeMode='Middle';d.pitchCue=0;if(!state.settings['Maintain Sync on Track Load'])d.sync=false;if(state.settings['Turn off FX'])state.fx[index%2].forEach(f=>f.on=false);state.focus=index;renderDecks();try{await engine.buffer(t);drawWaves();}catch(e){notify(e.message);}renderTracks();}
async function play(d){if(d.playing)engine.pause(d);else {try{await engine.start(d);d.track.plays++;state.history.push({id:d.track.id,title:d.track.title,time:new Date().toISOString(),deck:d.index+1});if(!state.settings['Retain Tracks in Prepare'])state.prepare=state.prepare.filter(id=>id!==d.track.id);}catch(e){return notify(e.message);}}renderDecks();renderTracks();}
function quantized(d,p){if(!state.quantize||!d.track?.bpm)return p;const value=parseFloat(state.settings['Quantize Value'])||1;const interval=state.settings['Quantize Value'].includes('/')?1/Number(state.settings['Quantize Value'].split('/')[1].split(' ')[0]):value;const beat=60/d.track.bpm*interval;return Math.round((p-(d.track.grid||0))/beat)*beat+(d.track.grid||0);}
async function deckAction(action,index,el,event={}){const d=state.decks[index];state.focus=index;if(action==='load')return load(index);if(action==='tab'){d.tab=el.dataset.tab;return renderDecks();}if(action==='eject'){engine.pause(d);d.previous=d.track?{id:d.track.id,position:d.position}:null;d.track=null;d.position=0;return renderDecks();}if(!d.track)return notify('Load a track first.');const pos=engine.position(d),beat=60/(d.track.bpm||120);
 if(action==='play')return play(d);
 if(action==='pad'){const n=Number(el.dataset.pad);if(d.tab==='Cues'){if(event.shiftKey)d.track.cues[n]=null;else if(d.track.cues[n]){await engine.seek(d,d.track.cues[n].position);if(state.flip.armed)state.flip.events.push({cue:n,position:d.track.cues[n].position,time:performance.now()});}else d.track.cues[n]={position:quantized(d,pos),name:`Cue ${n+1}`,color:colors[n]};persist();}
 else if(d.tab==='Loops'){const l=d.track.savedLoops[n];if(l){await engine.setLoop(d,true,l.start,l.end);await engine.seek(d,l.start);}else {d.track.savedLoops[n]={start:pos,end:Math.min(d.track.duration,pos+beat*d.loopLength),name:`Loop ${n+1}`};persist();}}
 else if(d.tab==='Stems'){if(n<4)d.stems[n]=!d.stems[n];else d.stemFX[n-4]=!d.stemFX[n-4];notify('Stem controls simulated. The full mix continues; no separation model is running.');}
 else if(d.tab==='Pitch'){d.keyShift=[0,1,2,3,-4,-3,-2,-1][n];if(event.shiftKey)d.pitchCue=n;notify(`Pitch Play ${d.keyShift} semitones · cue ${d.pitchCue+1} · simulation; audio is unchanged.`);}
 else {d.slice=n;notify(`Slice ${n+1} selected · domain simulation; audio is unchanged.`);}renderDecks();return;}
 if(action==='cue'){if(d.playing)await engine.seek(d,d.cue);else d.cue=quantized(d,pos);}
 if(action==='loop'){const start=quantized(d,pos),end=Math.min(d.track.duration,start+beat*d.loopLength);await engine.setLoop(d,!d.loop,d.loop?d.loopIn:start,d.loop?d.loopOut:end);}
 if(action==='loopHalf'||action==='loopDouble'){d.loopLength=clamp(d.loopLength*(action==='loopHalf'?.5:2),1/32,128);if(d.loop)await engine.setLoop(d,true,d.loopIn,Math.min(d.track.duration,d.loopIn+beat*d.loopLength));}
 if(action==='loopIn')d.loopIn=quantized(d,pos);
 if(action==='loopOut'){const end=quantized(d,pos);if(end<=d.loopIn)return notify('Loop Out must be after Loop In.');await engine.setLoop(d,true,d.loopIn,end);}
 if(action==='loopSave'){if(d.loopOut<=d.loopIn)return notify('Set a loop before saving.');d.track.savedLoops.push({start:d.loopIn,end:d.loopOut,name:`Loop ${d.track.savedLoops.length+1}`});persist();notify('Loop saved to this browser session.');}
 if(action==='jumpBack'||action==='jumpForward')await engine.seek(d,pos+beat*d.loopLength*(action==='jumpBack'?-1:1));
 if(action==='sync'){d.sync=!d.sync;const other=state.decks.find(o=>o!==d&&o.track);if(d.sync&&other){await engine.setRate(d,(other.track.bpm*other.rate)/(d.track.bpm||120));notify('Tempo matched in browser; Smart Sync phase and takeover are simulated.');}}
 if(['keylock','slip','reverse','repeat','pfl'].includes(action)){d[action]=!d[action];if(action!=='repeat')notify(`${action==='pfl'?'Headphone routing':action} is simulated; browser audio behavior is unchanged.`);}
 if(action==='range')d.pitchRange=({8:16,16:50,50:8})[d.pitchRange];
 if(action==='double'){const source=state.decks.find(o=>o.index!==index&&o.track);if(!source)return notify('Load the other deck first.');await load(index,source.track.id,{position:engine.position(source)});d.rate=source.rate;d.keylock=source.keylock;d.sync=source.sync;d.loop=source.loop;d.loopIn=source.loopIn;d.loopOut=source.loopOut;}
 if(action==='grid')return panels.grid(d);
 renderDecks();}
async function importFiles(files){let n=0;for(const file of files){if(!file.size)continue;const track={id:'local-'+crypto.randomUUID(),title:file.name.replace(/\.[^.]+$/,''),artist:'Local file',album:'Imported',bpm:0,key:'—',duration:0,type:file.name.split('.').pop().toUpperCase(),rating:0,plays:0,color:colors[n%8],file,cues:[],savedLoops:[],comment:'BPM/key unmeasured. Enter values in Track details.',grid:0,gridMarkers:[]};try{await engine.buffer(track);track.analyzed=true;state.tracks.push(track);n++;}catch{notify(`Cannot decode ${file.name}. Browser format support differs from native Serato.`);}}renderTracks();notify(`${n} local audio file${n===1?'':'s'} imported; files stay in this browser. BPM/key require annotation.`);}
async function analyze(){if(state.analysis){state.analysis=false;notify('Analysis queue cancelled.');return;}state.analysis=true;$('#analyze').textContent='Cancel analysis';const scope=$('#analysis-scope').value;const list=scope==='All tracks'?state.tracks:scope==='Current crate'?filtered():[trackById(state.selected)].filter(Boolean);for(const t of list){if(!state.analysis)break;if(t.locked)continue;try{await engine.buffer(t);t.analyzed=true;}catch{t.missing=true;}await new Promise(r=>setTimeout(r,80));renderTracks();}state.analysis=false;$('#analyze').textContent='Analyze';drawWaves();notify('Waveform decoding finished. BPM/key/gain analysis is not implemented; fixture annotations preserved.');}
