const api={state,engine,$,$$,esc,clone,colors,features,requirements,fxCatalog,providers,time,notify,dialog,persist,renderCrates,renderTracks,renderDecks,drawWaves,load,play,deckAction,trackById,filtered,download,reset,importFiles};
const panels=createPanels(api);
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-track],[data-focus]');if(!el)return;try{if(el.dataset.panel){panels.open(el.dataset.panel);return;}if(el.dataset.action){await deckAction(el.dataset.action,Number(el.dataset.deck),el,e);return;}if(el.dataset.crate){state.crate=el.dataset.crate;state.search='';$('#search').value='';renderCrates();renderTracks();return;}if(el.dataset.provider){panels.provider(el.dataset.provider);return;}if(el.dataset.sort){state.sortDir=state.sort===el.dataset.sort?-state.sortDir:1;state.sort=el.dataset.sort;renderTracks();return;}if(el.dataset.track){state.selected=el.dataset.track;$$('[data-track]').forEach(r=>{const selected=r.dataset.track===state.selected;r.classList.toggle('selected',selected);r.setAttribute('aria-selected',String(selected));});return;}if(el.dataset.focus){state.focus=Number(el.dataset.focus);$$('.deck').forEach(d=>d.classList.toggle('focused',Number(d.dataset.focus)===state.focus));}}catch(err){notify(err.message);}});
$('#tracks').addEventListener('dblclick',e=>{const r=e.target.closest('[data-track]');if(r)load(state.focus,r.dataset.track);});
document.addEventListener('contextmenu',e=>{const r=e.target.closest('[data-track]'),c=e.target.closest('[data-crate]'),p=e.target.closest('[data-action=pad]');if(r||c||p)e.preventDefault();if(r)panels.trackDetails(trackById(r.dataset.track));else if(c)panels.crateDetails(c.dataset.crate);else if(p)panels.editPad(state.decks[Number(p.dataset.deck)],Number(p.dataset.pad));});
document.addEventListener('input',e=>{if(e.target.dataset.tempo!==undefined){const d=state.decks[Number(e.target.dataset.tempo)];engine.setRate(d,1+Number(e.target.value)/100);$(`#platter-${d.index} strong`).textContent=d.track?(d.track.bpm*d.rate).toFixed(1):'—';}if(e.target.dataset.mix){const [i,k]=e.target.dataset.mix.split(':');state.decks[i][k]=Number(e.target.value);engine.mix(Number(i),k,e.target.value);}if(e.target.id==='crossfader')engine.setCross(Number(e.target.value));});
document.addEventListener('change',e=>{if(e.target.dataset.mode!==undefined){const d=state.decks[Number(e.target.dataset.mode)];d.mode=e.target.value;notify('Device modes are simulated. Browser audio remains in internal playback.');renderDecks();}});
document.addEventListener('click',e=>{const r=e.target.closest('[data-seek]');if(!r)return;const d=state.decks[Number(r.dataset.seek)];if(!d.track)return;if(d.playing&&state.settings['Disable Needle Search During Playback']&&!e.shiftKey)return notify('Needle search protected; hold Shift to override.');engine.seek(d,(e.clientX-r.getBoundingClientRect().left)/r.clientWidth*d.track.duration);});
document.addEventListener('pointerdown',e=>{const el=e.target.closest('[data-action=roll]');if(!el)return;const d=state.decks[Number(el.dataset.deck)];if(!d.track)return;d.rollStart=performance.now();d.rollPosition=engine.position(d);d.rollWasPlaying=d.playing;engine.setLoop(d,true,d.rollPosition,Math.min(d.track.duration,d.rollPosition+60/(d.track.bpm||120)*d.loopLength));el.setPointerCapture(e.pointerId);el.classList.add('active');});
document.addEventListener('pointerup',e=>{for(const d of state.decks){if(d.rollStart!=null){const p=d.rollPosition+(performance.now()-d.rollStart)/1000*d.rate*(d.rollWasPlaying?1:0);engine.setLoop(d,false,d.loopIn,d.loopOut);engine.seek(d,p);d.rollStart=null;renderDecks();}}});
document.addEventListener('dragstart',e=>{const t=e.target.closest('[data-track]');if(t)e.dataTransfer.setData('text/plain',t.dataset.track);});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-drop-deck],[data-crate],#tracks,[data-sample-drop],[data-scratch-drop]'))e.preventDefault();});
document.addEventListener('drop',e=>{const deck=e.target.closest('[data-drop-deck]'),crate=e.target.closest('[data-crate]');if(deck||crate||e.target.closest('#tracks')){e.preventDefault();if(e.dataTransfer.files.length){importFiles(e.dataTransfer.files);return;}const id=e.dataTransfer.getData('text/plain');if(deck)load(Number(deck.dataset.dropDeck),id);if(crate){const c=state.crates.find(c=>c.id===crate.dataset.crate);if(c&&!c.smart&&trackById(id)){if(!c.tracks.includes(id))c.tracks.push(id);persist();renderTracks();notify(`Added to ${c.name}`);}}}});
$('#search').oninput=e=>{state.search=e.target.value;renderTracks();};$('#crate-search').oninput=renderCrates;
$('#layout').onchange=e=>{state.layout=e.target.value;renderDecks();};$('#deck-count').onchange=e=>{state.deckCount=Number(e.target.value);state.focus=Math.min(state.focus,state.deckCount-1);if(state.deckCount===2)state.decks.slice(2).forEach(d=>engine.pause(d));renderDecks();};
$('#day').onclick=()=>document.body.classList.toggle('day');$('#quantize').onclick=e=>{state.quantize=!state.quantize;e.currentTarget.setAttribute('aria-pressed',state.quantize);};$('#autoplay').onclick=e=>{state.autoplay=!state.autoplay;e.currentTarget.setAttribute('aria-pressed',state.autoplay);};$('#art-grid').onclick=e=>{state.grid=!state.grid;e.currentTarget.setAttribute('aria-pressed',state.grid);renderTracks();};$('#new-crate').onclick=()=>panels.newCrate(false);$('#new-smart').onclick=()=>panels.newCrate(true);$('#import').onclick=()=>$('#audio-files').click();$('#audio-files').onchange=e=>importFiles(e.target.files);$('#analyze').onclick=analyze;$('#columns').onclick=()=>panels.columns();$('#library-tools').onclick=()=>panels.libraryTools();
document.addEventListener('keydown',async e=>{const tag=e.target.tagName;if(['INPUT','TEXTAREA','SELECT'].includes(tag)||$('#modal').open)return;const k=e.key.toLowerCase(),mod=e.metaKey||e.ctrlKey;if(mod&&k==='f'){e.preventDefault();$('#search').focus();return;}if(mod&&k==='p'){e.preventDefault();if(!state.prepare.includes(state.selected))state.prepare.push(state.selected);notify('Added to Prepare.');return;}if(mod&&k==='z'){e.preventDefault();const d=state.decks[state.focus];if(d.previous)load(d.index,d.previous.id,{position:d.previous.position});return;}if(e.shiftKey&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();return load(e.key==='ArrowLeft'?0:1);}if(['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const a=filtered(),i=a.findIndex(t=>t.id===state.selected),j=clamp(i+(e.key==='ArrowUp'?-1:1),0,a.length-1);if(a[j]){state.selected=a[j].id;renderTracks();$(`[data-track="${state.selected}"]`)?.scrollIntoView({block:'nearest'});}return;}if(e.target.dataset.seek!==undefined&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const d=state.decks[Number(e.target.dataset.seek)];engine.seek(d,engine.position(d)+(e.key==='ArrowLeft'?-1:1));return;}if(state.settings['Playback Keys Use Shift']&&!e.shiftKey&&!e.getModifierState('CapsLock'))return;if(k==='w'||k==='s'){e.preventDefault();await play(state.decks[k==='w'?0:1]);}if(/^[0-9]$/.test(k)){const n=(Number(k)+9)%10,d=state.decks[n<5?0:1];d.tab='Cues';await deckAction('pad',d.index,{dataset:{pad:String(n%5)}},e);}if(k==='i'||k==='k')await deckAction('cue',k==='i'?0:1,{},e);if(k==='o'||k==='p')await deckAction(k==='o'?'loopIn':'loopOut',0,{},e);const n='zxcvbnm,'.indexOf(k);if(n>=0&&k.length===1&&!mod){e.preventDefault();panels.sampleAction(n,e.altKey?'stop':'play');}});
engine.onSampleEnd=key=>{const slot=state.samples[Math.floor(key/8)]?.[key%8];if(slot)slot.playing=false;if(state.panel==='sampler')panels.refresh();};
engine.onEnd=async d=>{if(d.repeat){d.position=0;await engine.start(d);}else if(state.autoplay){const a=filtered(),i=a.findIndex(t=>t.id===d.track.id);if(a[i+1]){await load(d.index,a[i+1].id);await play(d);}}renderDecks();};
function tick(){for(const d of state.decks.slice(0,state.deckCount)){const p=engine.position(d),t=$(`#time-${d.index}`);if(t)t.textContent=time(p);const rem=$(`#remain-${d.index}`);if(rem)rem.textContent='−'+time((d.track?.duration||0)-p);const head=$(`#head-${d.index}`);if(head)head.style.left=`${p/(d.track?.duration||48)*100}%`;const platter=$(`#platter-${d.index}`);if(platter&&!state.settings['Reduced Motion'])platter.style.setProperty('--rotation',`${p*270}deg`);}$('#master-meter').value=engine.meter();$('#audio-status').textContent=`${state.decks.filter(d=>d.playing).length} decks playing · ${engine.ctx?.sampleRate||'—'} Hz browser · hardware simulated`;drawDetailWave();panels.tick();requestAnimationFrame(tick);}
